static long parse_signed_digits(const char *text) {
	int sign = 1;
	if (*text == '+') {
		text++;
	} else if (*text == '-') {
		sign = -1;
		text++;
	}
	long value = 0;
	while (isdigit((unsigned char)*text)) {
		value = value * 10 + *text++ - '0';
	}
	return sign * value;
}

