static bool read_command(char *command, size_t size) {
	char ch;
	while (running) {
		ssize_t count = read(serial_fd, &ch, 1);
		if (count == 1) {
			if (ch == ':') {
				break;
			}
		} else if (count < 0 && (errno == EINTR || errno == EAGAIN || errno == EWOULDBLOCK || errno == EIO)) {
			usleep(1000);
		} else if (count < 0) {
			return false;
		} else if (count == 0) {
			usleep(1000);
		}
	}
	size_t used = 0;
	while (running && used + 1 < size) {
		ssize_t count = read(serial_fd, &ch, 1);
		if (count == 1) {
			if (ch == '#') {
				command[used] = 0;
				return true;
			}
			command[used++] = ch;
		} else if (count < 0 && (errno == EINTR || errno == EAGAIN || errno == EWOULDBLOCK || errno == EIO)) {
			usleep(1000);
		} else if (count < 0) {
			return false;
		} else if (count == 0) {
			usleep(1000);
		}
	}
	command[used] = 0;
	return used > 0;
}

static void run_protocol_loop(void) {
	while (running) {
		char command[64];
		if (read_command(command, sizeof(command))) {
			handle_command(command);
		}
	}
}

int main(int argc, char *argv[]) {
	char port[256] = { 0 };

	if (!parse_args(argc, argv)) {
		return 1;
	}
	signal(SIGTERM, signal_handler);
	signal(SIGINT, signal_handler);
	signal(SIGPIPE, SIG_IGN);

	serial_fd = serial_simulator_open_pty(port, sizeof(port));
	if (serial_fd < 0) {
		return 1;
	}
	if (options.ready_file != NULL && !serial_simulator_write_ready_file(options.ready_file, simulator_name, port)) {
		close(serial_fd);
		return 1;
	}
	if (!options.headless) {
		printf("iOptron mount simulator ready on %s\n", port);
	}

	run_protocol_loop();
	if (serial_fd >= 0) {
		close(serial_fd);
	}
	return 0;
}
